  `expand_info` json NULL COMMENT '扩展信息',
  `context` int(2) UNSIGNED ZEROFILL NULL DEFAULT NULL COMMENT '客户阶段',
  `exclusive_server_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '专属客服ID',
  `exclusive_server_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '专属客服姓名',
  `rfm` decimal(6, 2) NULL DEFAULT NULL COMMENT 'rfm得分',
  `r_score` decimal(6, 2) NULL DEFAULT 0.00 COMMENT '最近一次消费距今天数，得分',
  `f_score` decimal(6, 2) NULL DEFAULT 0.00 COMMENT '最近一年消费次数，得分',
  `m_score` decimal(6, 2) NULL DEFAULT 0.00 COMMENT '最近一年消费总额，得分',
  `active_status` int(1) NULL DEFAULT NULL COMMENT '客户当前活跃度',
  `create_by_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人姓名',
  `new_customer_count` int(11) NULL DEFAULT NULL COMMENT '推荐客户数量',
  `share_tenant` json NULL COMMENT '共享门店',
  `source_type_second` int(11) NULL DEFAULT NULL COMMENT '第二来源类型,不包含线下渠道',
  `source_type_detail_all_second` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '第二来源具体的来源渠道',
  `source_path_name_second` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '第二来源路径名称',
  `source_type_third` int(11) NULL DEFAULT NULL COMMENT '第三来源类型,不包含线下渠道和老带新和scrm',
  `source_type_detail_all_third` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '第三来源具体的来源渠道',
  `source_path_name_third` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '第三来源路径名称',
  `first_treat_doctor_id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '首次分诊医生',
  `first_treat_doctor_id_new` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '首次分诊医生（编辑）',
  `latest_treat_doctor_id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '最近一次分诊医生',
  `urgent_contact_relationship` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `real_first_cost_date` datetime NULL DEFAULT NULL COMMENT '首次消费时间（有金额交易，不含储值定金等）',
  `first_cost_amount` decimal(15, 2) NULL DEFAULT NULL COMMENT '首次消费金额',
  `other_cost_amount_first_cost_year` decimal(15, 2) NULL DEFAULT NULL COMMENT '首次消费所在年，除首次消费的其他金额',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `vipNum`(`vip_num` ASC) USING BTREE,
  INDEX `idx_sys_user_id`(`sys_user_id` ASC) USING BTREE,
  INDEX `mainPhoneIndex`(`main_phone` ASC) USING BTREE,
  INDEX `index_update_date`(`update_date` ASC) USING BTREE,
  INDEX `index_tenant_id`(`tenant_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '\'neuron.consultation_view\' is not BASE TABLE' ROW_FORMAT = DYNAMIC;

